<?php
declare(strict_types=1);
require __DIR__ . '/includes/bootstrap.php';
require __DIR__ . '/includes/wholesale-portal.php';

header('Cache-Control: no-store, private');
header('Referrer-Policy: no-referrer');
header('X-Frame-Options: DENY');
header("Content-Security-Policy: frame-ancestors 'none'; base-uri 'self'; form-action 'self'");

if(!app_has_config())app_redirect('setup-first-user.php');
$pdo=app_pdo();app_boot_session();$token=trim((string)($_GET['token']??$_POST['token']??''));$invite=null;$error=null;
if($token!==''){$hash=hash('sha256',$token);$statement=$pdo->prepare("SELECT i.*,a.business_name,a.public_id AS account_public_id,o.name AS organization_name FROM wholesale_portal_invites i INNER JOIN wholesale_accounts a ON a.id=i.wholesale_account_id INNER JOIN organizations o ON o.id=i.organization_id WHERE i.token_hash=? AND i.accepted_at IS NULL AND i.revoked_at IS NULL AND i.expires_at>NOW(6) AND a.archived_at IS NULL LIMIT 1");$statement->execute([$hash]);$invite=$statement->fetch()?:null;}
if(!$invite)$error='This wholesale invitation is invalid, expired, or has already been used.';
if($_SERVER['REQUEST_METHOD']==='POST'&&$invite){
    $first=mb_substr(trim((string)($_POST['first_name']??'')),0,100,'UTF-8');$last=mb_substr(trim((string)($_POST['last_name']??'')),0,100,'UTF-8');$password=(string)($_POST['password']??'');$confirm=(string)($_POST['confirm_password']??'');
    if(!app_verify_csrf($_POST['csrf_token']??null))$error='The form expired. Refresh and try again.';
    elseif($first===''||$last==='')$error='Enter your first and last name.';
    elseif($password!==$confirm)$error='The passwords do not match.';
    elseif(!app_password_is_valid($password))$error='Use at least 12 characters with uppercase, lowercase, and a number.';
    else{
        $existing=$pdo->prepare('SELECT COUNT(*) FROM users WHERE email=? AND archived_at IS NULL');$existing->execute([$invite['email']]);
        if((int)$existing->fetchColumn()>0)$error='An account already exists for this email. Ask the wholesale team to link your existing login.';
        else{
            try{
                $pdo->beginTransaction();
                $lock=$pdo->prepare('SELECT accepted_at,revoked_at,expires_at FROM wholesale_portal_invites WHERE id=? FOR UPDATE');$lock->execute([(int)$invite['id']]);$inviteState=$lock->fetch();
                if(!$inviteState||$inviteState['accepted_at']!==null||$inviteState['revoked_at']!==null||strtotime((string)$inviteState['expires_at'])<=time())throw new RuntimeException('Invitation is no longer available.');
                $accountUsers=$pdo->prepare("SELECT id FROM wholesale_account_users WHERE wholesale_account_id=? AND status='active' FOR UPDATE");$accountUsers->execute([(int)$invite['wholesale_account_id']]);$isPrimary=count($accountUsers->fetchAll())===0?1:0;
                $hashPassword=app_password_hash($password);$display=trim($first.' '.$last);$userInsert=$pdo->prepare("INSERT INTO users (email,password_hash,first_name,last_name,display_name,status,email_verified_at,password_changed_at) VALUES (?,?,?,?,?,'active',NOW(6),NOW(6))");$userInsert->execute([$invite['email'],$hashPassword,$first,$last,$display]);$userId=(int)$pdo->lastInsertId();
                $membership=$pdo->prepare("INSERT INTO organization_memberships (organization_id,user_id,job_title,status) VALUES (?,?,'Wholesale Customer','active')");$membership->execute([(int)$invite['organization_id'],$userId]);$membershipId=(int)$pdo->lastInsertId();$roleId=wholesale_portal_role_id($pdo,(int)$invite['organization_id']);$pdo->prepare('INSERT INTO user_roles (membership_id,role_id,assigned_by) VALUES (?,?,?)')->execute([$membershipId,$roleId,(int)$invite['invited_by']]);
                $pdo->prepare("INSERT INTO wholesale_account_users (organization_id,wholesale_account_id,user_id,account_role,is_primary,status) VALUES (?,?,?,?,?,'active')")->execute([(int)$invite['organization_id'],(int)$invite['wholesale_account_id'],$userId,$invite['account_role'],$isPrimary]);$pdo->prepare('UPDATE wholesale_portal_invites SET accepted_at=NOW(6) WHERE id=? AND accepted_at IS NULL')->execute([(int)$invite['id']]);
                $pdo->commit();session_regenerate_id(true);$_SESSION['user_id']=$userId;$_SESSION['organization_id']=(int)$invite['organization_id'];$_SESSION['authenticated_at']=time();app_audit($pdo,(int)$invite['organization_id'],$userId,'wholesale.portal_invite_accepted','wholesale_account',(string)$invite['account_public_id'],null,['email'=>$invite['email'],'isPrimary'=>(bool)$isPrimary]);app_redirect('wholesale-portal.php');
            }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException&&$e->getMessage()==='Invitation is no longer available.'?$e->getMessage():'The wholesale account could not be created. Please contact the restaurant.';}
        }
    }
}
$business=$invite['business_name']??'Wholesale Customer';
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Wholesale Portal Invitation</title><style>:root{--ink:#171815;--muted:#6e716c;--line:#dfded8;--accent:#d94a2b;--bg:#f3f2ee}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:var(--bg);color:var(--ink);font-family:Inter,system-ui,-apple-system,Segoe UI,sans-serif}.shell{width:min(920px,94vw);display:grid;grid-template-columns:1fr 1fr;border:1px solid var(--line);border-radius:26px;overflow:hidden;background:#fff;box-shadow:0 24px 70px rgba(0,0,0,.12)}.hero{padding:42px;background:#171b1a;color:#fff}.hero .mark{width:48px;height:48px;display:grid;place-items:center;border-radius:15px;background:var(--accent);font-weight:900}.hero h1{margin:34px 0 12px;font-size:42px;line-height:.98;letter-spacing:-.05em}.hero p{color:#c8ccc8;line-height:1.6}.form{padding:42px}.eyebrow{color:var(--accent);font-size:10px;font-weight:900;text-transform:uppercase;letter-spacing:.12em}.form h2{margin:7px 0 5px;font-size:27px}.form>p{color:var(--muted);font-size:13px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:20px}.field-wrap{margin-bottom:12px}.field-wrap.wide{grid-column:1/-1}.field-wrap label{display:block;margin-bottom:5px;font-size:10px;font-weight:850}.field{width:100%;min-height:43px;padding:10px 11px;border:1px solid var(--line);border-radius:10px}.btn{width:100%;min-height:44px;border:0;border-radius:11px;background:var(--accent);color:#fff;font-weight:900}.message{padding:11px 13px;border-radius:10px;background:#fff0ef;color:#9c2f23;font-size:12px;margin:14px 0}.meta{padding:10px;border-radius:10px;background:#f7f6f2;font-size:11px;color:var(--muted)}@media(max-width:760px){.shell{grid-template-columns:1fr}.hero{padding:28px}.hero h1{font-size:33px}.form{padding:28px}}</style></head><body><main class="shell"><section class="hero"><div class="mark">G</div><h1>Your wholesale relationship now has a workspace.</h1><p>Review quotes and orders, submit reorders or sample requests, manage preferences, and ask your private wholesale AI assistant questions about your own account.</p></section><section class="form"><p class="eyebrow">Wholesale customer access</p><h2><?=app_escape($business)?></h2><p>Create the private buyer login linked only to this wholesale account.</p><?php if($error):?><div class="message"><?=app_escape($error)?></div><?php endif;?><?php if($invite):?><div class="meta">Invitation for <strong><?=app_escape($invite['email'])?></strong> · expires <?=app_escape((string)$invite['expires_at'])?></div><form method="post"><input type="hidden" name="csrf_token" value="<?=app_escape(app_csrf_token())?>"><input type="hidden" name="token" value="<?=app_escape($token)?>"><div class="grid"><div class="field-wrap"><label>First name</label><input class="field" name="first_name" required autocomplete="given-name"></div><div class="field-wrap"><label>Last name</label><input class="field" name="last_name" required autocomplete="family-name"></div><div class="field-wrap wide"><label>Password</label><input class="field" name="password" type="password" required autocomplete="new-password" placeholder="12+ characters, upper/lowercase and number"></div><div class="field-wrap wide"><label>Confirm password</label><input class="field" name="confirm_password" type="password" required autocomplete="new-password"></div><div class="field-wrap wide"><button class="btn" type="submit">Create wholesale portal account</button></div></div></form><?php else:?><p><a href="wholesale.php">Return to wholesale information</a></p><?php endif;?></section></main></body></html>
